attachment.snippet:
1	// Caption and status drawn into the 3D scene under the mirror. The Quest browser doesn't show
2	// the dom-overlay panel in passthrough AR, so in the headset the text has to be a textured plane.
3	import * as THREE from "three";
4	import { wrapLines } from "./wrap.js";
5	
6	const PX_PER_M = 2400; // canvas pixels per metre of panel
7	const FONT = '"IBM Plex Sans", system-ui, sans-serif';
8	
9	export function createCaption3d({ width = 0.5, height = 0.12, ink = "#15130f", paper = "#f3eee4", dusk = "#8a8378" } = {}) {
10	  const canvas = document.createElement("canvas");
11	  canvas.width = Math.round(width * PX_PER_M);
12	  canvas.height = Math.round(height * PX_PER_M);
13	  const ctx = canvas.getContext("2d");
14	  const texture = new THREE.CanvasTexture(canvas);
15	  texture.colorSpace = THREE.SRGBColorSpace;
16	  texture.anisotropy = 4;

